WITH cleaned AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, INITCAP(TRIM(promo_code)) AS promo_code_title, COALESCE(channel, 'N/A') AS channel_clean FROM promotions WHERE starts_on > TO_DATE('2023-05-13') AND channel IS NOT NULL AND channel = 'store') SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY discount_pct DESC, id) = 1
